window.__ADV3BANKS24["hd1-tet"] = (window.__ADV3BANKS24["hd1-tet"] || []).concat([{"p": "Sáng mùng một Tết, em vừa ngủ dậy và gặp ông bà ở phòng khách. Việc đầu tiên em nên làm là gì?", "a": "Chào và chúc Tết ông bà mạnh khoẻ", "w": ["Xin lì xì ngay trước khi chào hỏi", "Chạy ra sân chơi với các bạn hàng xóm", "Đòi ông bà mua bánh kẹo cho em"], "e": "Đầu năm mới, em chào hỏi và chúc Tết người lớn trước — đó là lễ phép.", "f": "X1"}, {"p": "Cô chú đến chơi nhà và mừng tuổi em một phong bao lì xì đỏ. Em nên làm gì?", "a": "Nhận bằng hai tay, cảm ơn và chúc Tết cô chú", "w": ["Giật lấy phong bao rồi chạy đi chơi", "Mở phong bao ra đếm tiền ngay tại chỗ", "Chê phong bao nhỏ và trả lại cô chú"], "e": "Nhận lì xì bằng hai tay và nói lời cảm ơn, chúc Tết là cách ứng xử đẹp.", "f": "X1"}, {"p": "Mùa đông lạnh giá vừa qua đi, cây cối đâm chồi nảy lộc, hoa đào nở hồng. Đó là mùa nào?", "a": "Mùa xuân", "w": ["Mùa hạ", "Mùa thu", "Vẫn là mùa đông"], "e": "Mùa xuân đến sau mùa đông, cây cối đâm chồi, trăm hoa đua nở.", "f": "K1"}, {"p": "Trước Tết, nhà em còn bừa bộn, bố mẹ rất bận. Em có thể giúp việc gì vừa sức?", "a": "Quét nhà và lau bàn ghế giúp bố mẹ", "w": ["Ngồi xem ti vi để bố mẹ tự dọn", "Bày thêm đồ chơi ra cho vui nhà", "Đi chơi nhà bạn cả ngày tránh việc"], "e": "Giúp bố mẹ việc nhỏ vừa sức là em đã góp phần đón Tết cùng gia đình.", "f": "X1"}]);
window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"hd1-tet": {"choose": [{"p": "Em theo bố mẹ đi chúc Tết nhà người thân. Em nên cư xử như thế nào?", "a": "Lễ phép chào hỏi và chúc Tết người lớn", "w": ["Chạy nhảy ồn ào khắp nhà người ta", "Tự ý mở tủ lạnh lấy đồ ăn ngay", "Không chào hỏi ai, chỉ ngồi nghịch điện thoại"], "e": "Chào hỏi, chúc Tết lễ phép thể hiện em là đứa trẻ ngoan.", "f": "X1"}, {"p": "Ngày Tết trời rất lạnh, em chuẩn bị ra ngoài chơi. Em nên chọn trang phục thế nào?", "a": "Mặc áo ấm và đội mũ len để giữ ấm", "w": ["Mặc áo mỏng cho thoải mái, đẹp mắt", "Mặc áo cộc tay như ngày mùa hè", "Không cần mặc thêm gì cho ấm"], "e": "Trời lạnh phải mặc đủ ấm để không bị cảm lạnh, ốm đau.", "f": "X1"}, {"p": "Ngày Tết nhà có rất nhiều bánh kẹo ngọt. Em nên ăn như thế nào để khoẻ mạnh?", "a": "Ăn vừa phải, vẫn ăn đủ bữa và ăn rau quả", "w": ["Ăn kẹo ngọt thay cơm cả ngày luôn", "Ăn càng nhiều kẹo càng tốt cho răng", "Giấu kẹo ăn một mình suốt đêm"], "e": "Ăn quá nhiều đồ ngọt làm hại răng và sức khoẻ; ăn uống điều độ mới tốt.", "f": "X1"}, {"p": "Em lỡ làm đổ cốc nước ra sàn nhà trong ngày Tết. Em nên làm gì?", "a": "Tự lấy khăn lau sạch và lần sau cẩn thận hơn", "w": ["Để nguyên cho người khác tự lau", "Đổ lỗi là em gái làm đổ nước", "Lấy thêm nước đổ ra cho đều sàn"], "e": "Làm đổ thì tự dọn dẹp — đó là người có trách nhiệm.", "f": "X1"}, {"p": "Hằng ngày, việc làm nào giúp cơ thể em luôn sạch sẽ, khoẻ mạnh?", "a": "Rửa tay, đánh răng và tắm gội sạch sẽ", "w": ["Chỉ rửa mặt một lần trong tuần", "Không cần tắm nếu không chơi bẩn", "Ăn xong không cần rửa tay gì cả"], "e": "Giữ vệ sinh thân thể mỗi ngày giúp em phòng tránh bệnh tật.", "f": "X1"}], "tf": [{"s": "Trước Tết, cả nhà cùng nhau dọn dẹp và trang trí nhà cửa.", "t": true, "e": "Đúng — dọn nhà đón Tết là phong tục đẹp của gia đình Việt."}, {"s": "Khi nhận lì xì, em không cần nói lời cảm ơn.", "t": false, "e": "Sai — nhận lì xì em phải cảm ơn và chúc Tết người mừng tuổi."}, {"s": "Chúc Tết ông bà, em chúc ông bà mạnh khoẻ, sống lâu.", "t": true, "e": "Đúng — đó là lời chúc Tết hay và ý nghĩa nhất với ông bà."}, {"s": "Ngày Tết, em có thể ăn bánh kẹo ngọt thay cơm cả ngày.", "t": false, "e": "Sai — ăn nhiều đồ ngọt hại răng và sức khoẻ, em vẫn phải ăn đủ bữa."}, {"s": "Trời lạnh ngày Tết, em nên mặc áo ấm khi ra ngoài.", "t": true, "e": "Đúng — mặc ấm giúp em tránh bị cảm lạnh."}, {"s": "Đi chúc Tết, em không cần chào hỏi người lớn trong nhà.", "t": false, "e": "Sai — đến nhà ai em cũng phải lễ phép chào hỏi người lớn."}], "blank": [{"p": "Đầu năm mới, em chúc ông bà mạnh …", "a": "khoẻ", "w": ["đẹp", "vui"], "e": "Lời chúc “mạnh khoẻ” mong ông bà luôn có sức khoẻ."}, {"p": "Khi nhận lì xì, em nói lời … ơn và chúc Tết.", "a": "cảm", "w": ["xin", "chúc"], "e": "“Cảm ơn” là lời đáp lễ phép khi nhận lì xì."}, {"p": "Trước ngày Tết, cả nhà cùng … dẹp nhà cửa.", "a": "dọn", "w": ["quét", "lau"], "e": "Dọn dẹp nhà cửa là việc làm trước Tết của mọi gia đình."}], "match": [["Trước ngày Tết", "Dọn dẹp nhà cửa đón Tết"], ["Nhận lì xì", "Cảm ơn và chúc Tết"], ["Chúc Tết ông bà", "Chúc mạnh khoẻ, sống lâu"], ["Trời lạnh ngày Tết", "Mặc áo ấm giữ gìn sức khoẻ"]]}});

