window.__ADV3BANKS24["tv1-read1"] = (window.__ADV3BANKS24["tv1-read1"] || []).concat([{"p": "Giờ ra chơi, em thấy một bạn ngồi một mình ở góc sân, mặt rất buồn. Em nên làm gì?", "a": "Đến hỏi thăm và rủ bạn chơi cùng", "w": ["Mặc kệ bạn, em chơi với nhóm của mình", "Chê bạn là người không có bạn bè", "Rủ các bạn khác không chơi với bạn ấy"], "e": "Quan tâm, rủ bạn chơi cùng giúp bạn hết buồn và thêm gắn bó.", "f": "X1"}, {"p": "Em rất muốn mượn quyển truyện tranh của bạn. Em nên nói thế nào?", "a": "Hỏi mượn nhẹ nhàng: “Bạn cho tớ mượn nhé?”", "w": ["Tự lấy truyện của bạn không cần hỏi", "Giật lấy truyện từ tay bạn đang đọc", "Đòi bạn đưa truyện cho em ngay lập tức"], "e": "Mượn đồ của bạn phải hỏi xin phép nhẹ nhàng, lễ phép.", "f": "X1"}, {"p": "Bạn em bị ngã ở sân trường, đầu gối bị trầy xước. Việc đầu tiên em nên làm là gì?", "a": "Đỡ bạn dậy và hỏi thăm bạn", "w": ["Đứng cười vì bạn ngã rất buồn cười", "Chạy đi chơi tiếp với bạn khác", "Đi qua như không nhìn thấy bạn"], "e": "Giúp đỡ bạn khi bạn gặp nạn là việc làm đẹp của tình bạn.", "f": "X1"}, {"p": "Buổi sáng đến lớp, em gặp cô giáo ngay ở cổng trường. Em nên làm gì?", "a": "Đứng lại chào cô giáo lễ phép", "w": ["Chạy vụt qua cô vào lớp thật nhanh", "Trốn sau lưng bạn để cô không thấy", "Chỉ chào khi nào cô nhìn thấy em"], "e": "Chào hỏi thầy cô lễ phép mỗi ngày là nếp sống đẹp của học sinh.", "f": "X1"}]);
window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"tv1-read1": {"choose": [{"p": "Khi chơi cùng các bạn, em nên cư xử như thế nào?", "a": "Vui vẻ hoà đồng, biết nhường nhịn bạn", "w": ["Tranh giành đồ chơi với bạn cho mình", "Chỉ chơi một mình, không chơi với ai", "Bắt các bạn phải làm theo ý em hết"], "e": "Nhường nhịn, hoà đồng giúp em có nhiều bạn bè yêu quý.", "f": "X1"}, {"p": "Bạn em bị điểm kém nên rất buồn, ngồi im không nói gì. Em nên làm gì?", "a": "An ủi và động viên bạn cố gắng hơn", "w": ["Chê bạn học dốt trước cả lớp luôn", "Khoe điểm cao của em để bạn buồn thêm", "Không chơi với bạn nữa từ hôm nay"], "e": "Lời động viên giúp bạn bớt buồn và cố gắng học tập hơn.", "f": "X1"}, {"p": "Khi chơi đùa, em lỡ xô ngã bạn. Em nên làm gì ngay?", "a": "Đỡ bạn dậy và xin lỗi bạn", "w": ["Bỏ chạy thật nhanh vào lớp ngồi", "Đổ lỗi là bạn tự ngã chứ không phải em", "Cười đùa cho qua chuyện ngã đau"], "e": "Làm bạn ngã thì phải đỡ bạn dậy và xin lỗi — đó là người biết lỗi.", "f": "X1"}, {"p": "Em muốn vào chơi cùng nhóm bạn đang chơi ở góc sân. Em nên làm gì?", "a": "Xin phép nhẹ nhàng và chờ bạn đồng ý", "w": ["Chen ngay vào giữa làm hỏng trò chơi", "Giật lấy đồ chơi của nhóm bạn đó", "Đứng khóc để các bạn phải cho chơi"], "e": "Xin phép trước khi tham gia là cách cư xử lịch sự, tôn trọng bạn.", "f": "X1"}, {"p": "Hôm nay em đến lớp rất sớm, trong lớp chưa có bạn nào. Em nên làm gì?", "a": "Ngồi vào chỗ của mình, chờ cô và các bạn", "w": ["Chạy nhảy khắp lớp cho đỡ buồn chán", "Mở cặp của các bạn ra xem đồ chơi", "Vẽ bậy lên bảng và bàn ghế của lớp"], "e": "Đến sớm, em ngồi ngoan vào chỗ, giữ gìn lớp học sạch đẹp.", "f": "X1"}], "tf": [{"s": "Thấy bạn bị ngã, em nên đỡ bạn dậy và hỏi thăm.", "t": true, "e": "Đúng — giúp bạn khi bạn gặp khó khăn là việc làm tốt."}, {"s": "Chơi với bạn, em nên tranh giành đồ chơi của bạn.", "t": false, "e": "Sai — chơi với bạn phải biết nhường nhịn, chia sẻ."}, {"s": "Có bạn mới vào lớp, em nên chào bạn và làm quen.", "t": true, "e": "Đúng — chào hỏi thân thiện giúp bạn mới đỡ bỡ ngỡ."}, {"s": "Muốn mượn đồ của bạn, em cứ tự lấy không cần hỏi.", "t": false, "e": "Sai — mượn đồ phải hỏi xin phép bạn trước."}, {"s": "Khi bạn buồn, em nên an ủi và động viên bạn.", "t": true, "e": "Đúng — lời an ủi giúp bạn vơi đi nỗi buồn."}, {"s": "Đến lớp gặp thầy cô, em không cần chào hỏi gì.", "t": false, "e": "Sai — em phải lễ phép chào hỏi thầy cô mỗi ngày."}], "blank": [{"p": "Đến lớp, em được gặp bạn bè và … cô mỗi ngày.", "a": "thầy", "w": ["cô giáo", "bạn"], "e": "Từ đúng là “thầy” — thầy cô là người dạy em ở lớp."}, {"p": "Thấy bạn bị ngã, em chạy đến … bạn dậy.", "a": "đỡ", "w": ["xô", "đẩy"], "e": "Đỡ bạn dậy là giúp bạn đứng lên khi bị ngã."}, {"p": "Có bạn mới vào lớp, em … bạn và làm quen.", "a": "chào", "w": ["chê", "trêu"], "e": "Chào bạn là cách làm quen thân thiện nhất."}], "match": [["Bạn bị ngã", "Đỡ bạn dậy ngay"], ["Bạn đang buồn", "An ủi, động viên bạn"], ["Bạn mới vào lớp", "Chào bạn và làm quen"], ["Mượn đồ của bạn", "Hỏi mượn nhẹ nhàng"]]}});

