window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"dd1-safe": {"blank": [{"p": "Hộp thuốc của bà để ở ngăn tủ thấp, em nhìn thấy những viên thuốc nhiều màu như kẹo. Em không tự lấy và gọi bà đến để ...", "a": "Không ăn nhầm thuốc nguy hiểm", "w": ["Ăn thử một viên cho biết", "Giấu hộp thuốc đi chỗ khác"], "e": "Thuốc không phải kẹo, em không tự lấy thuốc khi không có người lớn."}, {"p": "Mẹ đang nấu bếp ga, lửa cháy xanh và nồi đang sôi. Em đứng xa bếp và không đến gần để ...", "a": "Không bị bỏng và an toàn", "w": ["Xem lửa cháy cho rõ hơn", "Giúp mẹ nhấc nồi xuống"], "e": "Bếp đang nấu rất nóng, em đứng xa để tránh bị bỏng."}, {"p": "Các bạn rủ em ra chơi bóng ngay lề đường có nhiều xe chạy qua. Em rủ các bạn vào sân trường chơi để ...", "a": "Chơi an toàn, tránh xa xe cộ", "w": ["Chơi bóng vui hơn hẳn", "Nhặt bóng nhanh hơn nhiều"], "e": "Chơi ở nơi an toàn, tránh xa đường xe chạy giúp phòng tai nạn."}, {"p": "Em chưa biết bơi, bạn rủ em xuống chỗ nước sâu ở hồ bơi. Em ở lại chỗ nước nông có người lớn trông để ...", "a": "An toàn khi ở dưới nước", "w": ["Bơi giỏi ngay lập tức", "Bạn khen em gan dạ"], "e": "Chưa biết bơi, em chỉ ở chỗ nước nông và có người lớn trông."}, {"p": "Dây sạc điện thoại bị đứt, lộ dây đồng bên trong. Em không cắm sạc và báo ngay cho bố để ...", "a": "Tránh bị điện giật nguy hiểm", "w": ["Sạc điện thoại nhanh hơn", "Tự nối dây lại dùng tiếp"], "e": "Dây điện hở rất nguy hiểm, em không chạm vào và báo người lớn."}, {"p": "Trời vừa mưa xong, sân trường còn ướt và trơn. Em đi chậm và bước cẩn thận để ...", "a": "Không bị trượt ngã", "w": ["Đến lớp nhanh hơn bạn", "Sân khô nhanh hơn hẳn"], "e": "Sân ướt dễ trơn trượt, đi chậm giúp em không bị ngã."}, {"p": "Đèn đỏ đang sáng ở ngã tư, em và bố đứng chờ trên vỉa hè. Hai bố con chờ đèn xanh mới sang đường để ...", "a": "Sang đường an toàn", "w": ["Sang đường nhanh hơn xe", "Không phải nhìn xe nữa"], "e": "Chờ đèn xanh và đi cùng người lớn giúp sang đường an toàn."}, {"p": "Con dao nhỏ để trên bàn thấp, em bé đang bò đến gần và với tay. Em gọi mẹ cất dao lên cao ngay để ...", "a": "Em bé không chạm vào dao sắc", "w": ["Em bé chơi dao an toàn", "Mẹ gọt hoa quả nhanh hơn"], "e": "Dao sắc phải để xa tầm tay trẻ nhỏ để tránh đứt tay."}, {"p": "Em ăn một viên kẹo tròn to, em ngồi yên nhai kĩ rồi mới nuốt để ...", "a": "Không bị hóc kẹo nguy hiểm", "w": ["Ăn được nhiều kẹo hơn", "Chạy chơi ngay được luôn"], "e": "Ngồi yên và nhai kĩ khi ăn giúp em không bị hóc, sặc."}, {"p": "Ngoài sân có nắng to và trời rất nóng giữa trưa. Em vào bóng mát và uống nước để ...", "a": "Không bị say nắng và mệt", "w": ["Chơi ngoài nắng lâu hơn", "Da đen đi cho khoẻ"], "e": "Tránh nắng gắt giữa trưa và uống nước giúp em không bị say nắng."}], "choose": [{"f": "X1", "p": "Việc làm nào giúp em an toàn khi đi bơi?", "a": "Bơi ở chỗ nông và có người lớn trông", "w": ["Tự xuống chỗ nước sâu một mình", "Nhảy từ trên cao xuống nước", "Bơi xa bờ không ai biết"], "e": "Đi bơi an toàn là ở chỗ nông và luôn có người lớn trông."}, {"f": "X1", "p": "Thấy dây điện bị đứt hở, em nên làm gì?", "a": "Tránh xa và báo người lớn ngay", "w": ["Cầm tay kiểm tra xem có điện không", "Tự lấy băng dính quấn lại", "Rủ bạn cùng xem cho vui"], "e": "Điện rất nguy hiểm, em tránh xa và báo người lớn xử lí."}, {"f": "X1", "p": "Vì sao em không được chơi gần ao hồ một mình?", "a": "Vì dễ ngã xuống nước rất nguy hiểm", "w": ["Vì ao hồ không có cá đẹp", "Vì nước ao hồ rất lạnh", "Vì bạn bè không thích chơi ở đó"], "e": "Chơi gần ao hồ một mình dễ ngã xuống nước, rất nguy hiểm."}, {"f": "X1", "p": "Khi ăn kẹo và đồ ăn nhỏ tròn, em nên làm gì để an toàn?", "a": "Ngồi yên và nhai kĩ trước khi nuốt", "w": ["Vừa chạy nhảy vừa ăn cho vui", "Cười đùa thật to khi đang ăn", "Ngậm kẹo rồi nằm ngủ luôn"], "e": "Ngồi yên nhai kĩ giúp em không bị hóc khi ăn."}], "tf": [{"s": "Đi bơi, em cần có người lớn đi cùng và ở chỗ nước nông.", "t": true, "e": "Đúng, đi bơi phải có người lớn trông và ở nơi an toàn."}, {"s": "Ổ điện và dây điện hở, em lấy que chọc vào xem cho vui.", "t": false, "e": "Sai, điện rất nguy hiểm, em không được chạm vào ổ điện."}, {"s": "Nồi canh vừa nấu xong rất nóng, em tránh xa không tự chạm vào.", "t": true, "e": "Đúng, đồ nóng dễ gây bỏng, em không tự ý chạm vào."}, {"s": "Sang đường một mình chạy thật nhanh là an toàn nhất.", "t": false, "e": "Sai, em sang đường cùng người lớn và đi trên vạch an toàn."}, {"s": "Thuốc của người lớn trông giống kẹo, em cũng không tự ăn thử.", "t": true, "e": "Đúng, thuốc không phải kẹo, ăn nhầm thuốc rất nguy hiểm."}, {"s": "Chạy nhảy đùa nghịch trên cầu thang giúp em đi nhanh hơn và an toàn.", "t": false, "e": "Sai, chạy nhảy trên cầu thang dễ ngã, em đi chậm và bám tay vịn."}], "match": [["Đi bơi", "để có người lớn trông và dùng phao"], ["Dây điện bị hở", "để tránh xa và báo người lớn"], ["Nồi canh đang sôi", "để đứng xa tránh bị bỏng"], ["Sang đường", "để đi cùng người lớn trên vạch an toàn"], ["Dao sắc trên bàn thấp", "để cất lên cao xa tầm tay em bé"], ["Sân ướt sau mưa", "để đi chậm tránh trượt ngã"]]}});
