(function(){var b=window.__ADV4BANKS24["dd1-self"]=window.__ADV4BANKS24["dd1-self"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Việc làm nào thể hiện em tự giác nhất?", "a": "Tự làm bài tập mà không chờ ai nhắc", "w": ["Chờ mẹ nhắc nhiều lần mới làm bài", "Nhờ chị làm hộ bài tập của em", "Để bài tập đến mai làm cũng được"], "e": "Tự làm bài của mình không cần nhắc là biểu hiện tự giác."}, {"f": "X1", "p": "Vì sao em nên tự làm những việc vừa sức của mình?", "a": "Để em tự lập và bố mẹ đỡ vất vả", "w": ["Để em không phải đi học nữa", "Để bạn bè phải phục vụ em", "Để em được chơi điện thoại nhiều hơn"], "e": "Tự làm việc vừa sức giúp em tự lập và đỡ đần bố mẹ."}, {"f": "X1", "p": "Bút của em hết mực giữa giờ học, em nên làm gì trước tiên?", "a": "Tự lấy bút dự phòng trong cặp ra dùng", "w": ["Khóc và chờ cô đến giúp", "Mượn bút của bạn cả buổi học", "Bỏ luôn bài không viết nữa"], "e": "Chuẩn bị bút dự phòng và tự xử lí việc nhỏ là tự giác."}, {"f": "X1", "p": "Được giao việc tưới cây nhưng em đang xem ti vi hay, em nên làm gì?", "a": "Tưới cây xong rồi xem tiếp", "w": ["Để mai tưới bù hai lần nước", "Nhờ em nhỏ tưới thay em", "Giả vờ đã tưới cây rồi"], "e": "Việc được giao em cần làm ngay, không trì hoãn hay nói dối."}]);b.tf=(b.tf||[]).concat([{"s": "Bài tập về nhà là việc của em, em tự giác làm trước khi chơi.", "t": true, "e": "Đúng, em làm bài của mình xong rồi mới chơi là tự giác."}, {"s": "Việc gì của em, em cũng chờ bố mẹ nhắc mới làm.", "t": false, "e": "Sai, em cần tự giác làm việc của mình, không chờ nhắc."}, {"s": "Quên việc được giao, em cứ bỏ qua không cần làm nữa.", "t": false, "e": "Sai, quên việc em cần nhận lỗi và làm ngay việc đó."}, {"s": "Tự chuẩn bị bình nước và cặp sách từ tối hôm trước là tự giác.", "t": true, "e": "Đúng, chuẩn bị trước giúp em chủ động và không quên đồ."}, {"s": "Không hiểu bài, em chép bài của bạn cho xong là tự giác học tập.", "t": false, "e": "Sai, chưa hiểu bài em cần hỏi thầy cô hoặc bố mẹ để hiểu thật."}]);b.blank=(b.blank||[]).concat([{"p": "Sáng nay chuông báo thức reo, em tự dậy, tự mặc quần áo đi học mà không cần mẹ gọi nhiều lần để ...", "a": "Em tự giác và đến lớp đúng giờ", "w": ["Mẹ phải gọi thêm nhiều lần", "Em được ngủ thêm một giấc"], "e": "Tự dậy và chuẩn bị đi học thể hiện em tự giác."}, {"p": "Trước khi ra khỏi nhà, em tự soi gương, chải lại tóc và cài cúc áo cho ngay ngắn để ...", "a": "Trông gọn gàng khi đến lớp", "w": ["Mẹ phải làm giúp hết", "Em đến lớp muộn hơn bạn"], "e": "Tự chăm sóc vẻ ngoài gọn gàng là việc em tự làm được."}, {"p": "Tối hôm trước, em tự cho bình nước vào cặp sách để ...", "a": "Sáng mai có nước uống ở lớp", "w": ["Sáng mai mẹ phải nhắc nữa", "Cặp sách nặng thêm vô ích"], "e": "Tự chuẩn bị đồ dùng từ tối hôm trước là thói quen tự giác."}, {"p": "Dây giày của em bị tuột khi đang chơi. Em ngồi xuống tự buộc lại dây giày để ...", "a": "Đi lại an toàn, không vấp ngã", "w": ["Nhờ bạn buộc giúp mỗi lần", "Cởi giày đi chân đất luôn"], "e": "Tự buộc dây giày là việc nhỏ em tự làm được."}, {"p": "Cô dạy một bài hát mới, em chưa thuộc lời. Mỗi tối em tự hát lại vài lần để ...", "a": "Thuộc bài hát cô dạy", "w": ["Khỏi cần hát ở lớp nữa", "Được cô cho nghỉ học"], "e": "Tự ôn lại bài ở nhà giúp em thuộc bài nhanh hơn."}, {"p": "Hộp bút của em đầy vụn chì và rác nhỏ. Em tự đổ rác và xếp lại bút gọn gàng để ...", "a": "Lấy bút dùng nhanh và hộp sạch", "w": ["Hộp bút tự sạch luôn", "Bạn phải dọn giúp em"], "e": "Tự dọn đồ dùng học tập của mình là việc em nên làm."}, {"p": "Ăn trưa xong ở trường, em tự mang khay cơm của mình để vào đúng chỗ quy định để ...", "a": "Giữ nhà ăn gọn gàng, sạch sẽ", "w": ["Bạn khác dọn thay em", "Khay cơm tự biến mất"], "e": "Tự dọn phần của mình sau bữa ăn là tự giác."}, {"p": "Em muốn đọc truyện nhưng quyển truyện để ở phòng khác. Em tự đi lấy truyện về đọc để ...", "a": "Không làm phiền người khác", "w": ["Mẹ phải đi lấy giúp em", "Em bỏ không đọc nữa"], "e": "Việc vừa sức của mình, em tự làm không làm phiền người khác."}, {"p": "Chậu hoa nhỏ của lớp đến lượt em chăm trong tuần này. Mỗi sáng em tự tưới nước cho hoa để ...", "a": "Hoa tươi tốt và lớp thêm đẹp", "w": ["Hoa tự lớn không cần nước", "Bạn khác tưới thay em"], "e": "Tự làm việc được giao giúp hoa tươi tốt, lớp đẹp hơn."}, {"p": "Bài đọc hôm nay hơi dài, em đọc còn chậm. Em tự đọc lại bài ở nhà thêm một lần để ...", "a": "Đọc trôi chảy hơn vào ngày mai", "w": ["Không cần đọc ở lớp nữa", "Cô không gọi em đọc bài"], "e": "Tự luyện đọc thêm ở nhà giúp em tiến bộ mỗi ngày."}]);b.match=(b.match||[]).concat([["Chuông báo thức reo buổi sáng", "để tự dậy và chuẩn bị đi học"], ["Bình nước cho ngày mai", "để tự cho vào cặp từ tối hôm trước"], ["Dây giày bị tuột", "để tự buộc lại cho an toàn"], ["Hộp bút đầy vụn chì", "để tự dọn sạch và xếp gọn"], ["Khay cơm ăn xong", "để tự mang để vào đúng chỗ"], ["Chậu hoa được giao chăm", "để tự tưới nước mỗi sáng"]]);})();
