window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"g1-addsub100": {"blank": [{"p": "Thư viện có 40 quyển truyện. Các bạn mang đến góp thêm 30 quyển nữa. Thư viện có tất cả ... quyển truyện.", "a": "70", "w": ["60", "80"], "e": "40 + 30 = 70 quyển truyện."}, {"p": "Một hộp có 85 viên bi. Em lấy ra 25 viên để chơi. Trong hộp còn lại ... viên bi.", "a": "60", "w": ["50", "70"], "e": "85 - 25 = 60 viên bi."}, {"p": "Lan dán tem vào vở. Vở đã có 56 con tem, Lan dán thêm 3 con nữa. Vở có tất cả ... con tem.", "a": "59", "w": ["58", "60"], "e": "56 + 3 = 59 con tem."}, {"p": "Rổ cam có 78 quả. Mẹ bán đi 8 quả ở chợ. Rổ cam còn lại ... quả.", "a": "70", "w": ["60", "80"], "e": "78 - 8 = 70 quả cam."}, {"p": "Đội trồng cây trồng được 20 cây buổi sáng và 45 cây buổi chiều. Cả ngày đội trồng được ... cây.", "a": "65", "w": ["55", "75"], "e": "20 + 45 = 65 cây."}, {"p": "Sợi dây dài 99 xăng-ti-mét. Em cắt đi 50 xăng-ti-mét. Sợi dây còn lại ... xăng-ti-mét.", "a": "49", "w": ["39", "59"], "e": "99 - 50 = 49 xăng-ti-mét."}, {"p": "Lớp 1A có 34 bạn, lớp 1B có 24 bạn. Hai lớp có tất cả ... bạn.", "a": "58", "w": ["48", "68"], "e": "34 + 24 = 58 bạn."}, {"p": "Một thùng có 67 quả bóng. Các bạn lấy ra 35 quả để tập. Trong thùng còn lại ... quả bóng.", "a": "32", "w": ["22", "42"], "e": "67 - 35 = 32 quả bóng."}, {"p": "Em đã đọc 15 trang sách. Em đọc thêm 80 trang nữa trong tuần này. Em đã đọc tất cả ... trang sách.", "a": "95", "w": ["85", "90"], "e": "15 + 80 = 95 trang sách."}, {"p": "Hội trường có 90 chiếc ghế. Các bạn mang ra sân 60 chiếc. Hội trường còn lại ... chiếc ghế.", "a": "30", "w": ["20", "40"], "e": "90 - 60 = 30 chiếc ghế."}], "choose": [{"f": "X1", "p": "Một thùng có 50 quả táo. Các bạn lấy ra 20 quả để ăn. Thùng còn lại mấy quả táo?", "a": "30 quả", "w": ["70 quả", "40 quả", "25 quả"], "e": "50 - 20 = 30 quả táo."}, {"f": "X1", "p": "Bạn Hoa đặt tính 45 + 30 và được kết quả 65. Bạn tính đúng hay sai?", "a": "Sai, kết quả đúng là 75", "w": ["Đúng, kết quả là 65", "Sai, kết quả đúng là 85", "Sai, kết quả đúng là 70"], "e": "45 + 30 = 75 nên kết quả 65 là sai."}, {"f": "X1", "p": "Số nào cộng với 40 thì được 90?", "a": "50", "w": ["40", "60", "30"], "e": "50 + 40 = 90 nên số cần tìm là 50."}, {"f": "X1", "p": "Cửa hàng có 78 cái áo. Cửa hàng bán được 8 cái áo. Câu nào nói đúng số áo còn lại?", "a": "Còn lại 70 cái áo", "w": ["Còn lại 86 cái áo", "Còn lại 78 cái áo", "Còn lại 60 cái áo"], "e": "78 - 8 = 70 cái áo còn lại."}], "tf": [{"s": "Khi cộng một số với số tròn chục, hàng đơn vị của số đó giữ nguyên.", "t": true, "e": "Đúng, cộng số tròn chục chỉ làm hàng chục thay đổi."}, {"s": "56 + 3 = 86.", "t": false, "e": "Sai, 56 + 3 = 59; cộng 3 vào hàng đơn vị, không cộng vào hàng chục."}, {"s": "Đặt tính cộng, trừ phải viết hàng đơn vị thẳng hàng đơn vị, hàng chục thẳng hàng chục.", "t": true, "e": "Đúng, đặt thẳng cột rồi tính từ hàng đơn vị trước."}, {"s": "90 - 40 = 40.", "t": false, "e": "Sai, 90 - 40 = 50."}, {"s": "35 + 24 = 59.", "t": true, "e": "Đúng, 35 + 24 = 59, cộng không nhớ từng hàng."}, {"s": "77 - 7 = 77.", "t": false, "e": "Sai, 77 - 7 = 70."}], "match": [["40 + 30", "70"], ["85 - 25", "60"], ["56 + 3", "59"], ["64 + 20", "84"], ["95 - 45", "50"], ["23 + 6", "29"]]}});
window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"mt1-mix": {"blank": [{"p": "Em muốn tô mặt trời mọc màu cam ấm. Em pha màu đỏ với màu ...", "a": "Vàng", "w": ["Xanh lam", "Trắng"], "e": "Đỏ pha với vàng được màu cam."}, {"p": "Em muốn tô bông hoa cà màu tím nhẹ. Em pha màu đỏ với màu ...", "a": "Xanh lam", "w": ["Vàng", "Trắng"], "e": "Đỏ pha với xanh lam được màu tím."}, {"p": "Em muốn tô thảm cỏ xanh tươi. Em pha màu vàng với màu ...", "a": "Xanh lam", "w": ["Đỏ", "Trắng"], "e": "Vàng pha với xanh lam được màu xanh lá."}, {"p": "Em tô chiếc áo của bạn trong tranh màu cam. Chiếc áo đó là màu pha từ đỏ và ...", "a": "Vàng", "w": ["Xanh lam", "Đen"], "e": "Màu cam là màu pha từ đỏ và vàng."}, {"p": "Em tô chùm nho chín trong tranh. Em pha đỏ với xanh lam để được màu ...", "a": "Tím", "w": ["Cam", "Xanh lá"], "e": "Đỏ pha xanh lam được tím, hợp để tô nho chín."}, {"p": "Em tô lá cây hai bên đường. Em pha vàng với xanh lam để được màu ...", "a": "Xanh lá", "w": ["Tím", "Cam"], "e": "Vàng pha xanh lam được xanh lá, hợp để tô lá cây."}, {"p": "Em muốn tô chiếc váy búp bê màu hồng xinh. Em pha màu đỏ với màu ...", "a": "Trắng", "w": ["Xanh lam", "Vàng"], "e": "Đỏ pha với trắng được màu hồng."}, {"p": "Em pha màu đỏ với màu trắng trong khay màu. Màu em nhận được là màu ...", "a": "Hồng", "w": ["Tím", "Cam"], "e": "Đỏ pha trắng được màu hồng nhạt."}, {"p": "Bạn pha được màu tím nhưng muốn tím nhạt hơn. Bạn cho thêm vào màu ...", "a": "Trắng", "w": ["Đỏ", "Xanh lam"], "e": "Thêm màu trắng làm màu tím nhạt dần đi."}, {"p": "Em tô củ cà rốt trong tranh rau quả. Em pha đỏ với vàng để củ cà rốt có màu ...", "a": "Cam", "w": ["Tím", "Xanh lá"], "e": "Đỏ pha vàng được cam, đúng màu củ cà rốt."}], "choose": [{"f": "X1", "p": "Em muốn tô bông hoa màu tím nhưng trên khay chỉ có màu đỏ, vàng và xanh lam. Em pha thế nào?", "a": "Pha đỏ với xanh lam", "w": ["Pha đỏ với vàng", "Pha vàng với xanh lam", "Chỉ dùng một màu vàng"], "e": "Đỏ pha xanh lam được màu tím để tô hoa."}, {"f": "X1", "p": "Vì sao màu cam được gọi là màu pha?", "a": "Vì màu cam có được do pha đỏ với vàng", "w": ["Vì màu cam tự có trong nắng", "Vì màu cam là màu cơ bản nhất", "Vì màu cam pha từ đen và trắng"], "e": "Cam không phải màu cơ bản, nó được pha từ đỏ và vàng."}, {"f": "X1", "p": "Bạn pha đỏ với trắng được màu hồng nhạt. Nếu muốn màu hồng đậm hơn, bạn làm gì?", "a": "Cho thêm màu đỏ vào", "w": ["Cho thêm nhiều màu trắng", "Cho thêm màu vàng vào", "Đổ hết khay màu đi"], "e": "Thêm đỏ làm màu hồng đậm dần lên."}, {"f": "X1", "p": "Em có màu vàng và màu xanh lam. Em pha hai màu này lại để tô vật nào cho giống thật nhất?", "a": "Tô chiếc lá cây", "w": ["Tô quả nho chín", "Tô mặt trời mọc", "Tô quả cà chua"], "e": "Vàng pha xanh lam được xanh lá, hợp nhất để tô lá cây."}], "tf": [{"s": "Pha màu đỏ với màu vàng được màu cam.", "t": true, "e": "Đúng, đỏ + vàng = cam."}, {"s": "Pha màu vàng với màu xanh lam được màu tím.", "t": false, "e": "Sai, vàng + xanh lam = xanh lá, không phải tím."}, {"s": "Pha màu đỏ với màu trắng được màu hồng.", "t": true, "e": "Đúng, đỏ + trắng = hồng."}, {"s": "Pha màu đỏ với màu xanh lam được màu xanh lá.", "t": false, "e": "Sai, đỏ + xanh lam = tím, không phải xanh lá."}, {"s": "Cho thêm màu trắng vào màu đỏ làm màu nhạt dần thành hồng.", "t": true, "e": "Đúng, thêm trắng làm màu đỏ nhạt thành hồng."}, {"s": "Pha màu đen với màu trắng thì được màu cam.", "t": false, "e": "Sai, màu cam được pha từ đỏ và vàng."}], "match": [["Màu đỏ và màu vàng", "để pha thành màu cam ấm"], ["Màu vàng và màu xanh lam", "để pha thành màu xanh lá tươi"], ["Màu đỏ và màu xanh lam", "để pha thành màu tím nhẹ"], ["Màu đỏ và màu trắng", "để pha thành màu hồng nhạt"], ["Khay màu của em", "để giữ các màu sạch không lẫn nhau"], ["Chiếc cọ vẽ sạch", "để màu pha không bị bẩn màu"]]}});
window.__ADV4BANKS24 = Object.assign(window.__ADV4BANKS24 || {}, {"mt1-lines": {"blank": [{"p": "Em vẽ cột cờ cao đứng ở giữa sân trường. Cột cờ hợp nhất với ...", "a": "Nét thẳng", "w": ["Nét xoắn", "Nét cong"], "e": "Cột cờ đứng thẳng nên vẽ bằng nét thẳng."}, {"p": "Em vẽ sợi dây phơi quần áo bị võng xuống ở giữa. Sợi dây hợp nhất với ...", "a": "Nét cong", "w": ["Nét thẳng", "Nét gấp khúc"], "e": "Dây phơi võng xuống được vẽ bằng nét cong."}, {"p": "Em vẽ dãy núi xa có nhiều đỉnh nhọn nhấp nhô. Dãy núi hợp nhất với ...", "a": "Nét gấp khúc", "w": ["Nét cong", "Nét xoắn"], "e": "Dãy núi nhọn nhấp nhô vẽ bằng nét gấp khúc."}, {"p": "Em vẽ chiếc lò xo nhỏ trong cây bút bi. Chiếc lò xo hợp nhất với ...", "a": "Nét xoắn", "w": ["Nét thẳng", "Nét cong"], "e": "Lò xo cuộn vòng nên vẽ bằng nét xoắn."}, {"p": "Em vẽ đường ray xe lửa chạy thẳng tắp về xa. Đường ray hợp nhất với ...", "a": "Nét thẳng", "w": ["Nét cong", "Nét xoắn"], "e": "Đường ray thẳng tắp nên vẽ bằng nét thẳng."}, {"p": "Em vẽ mái tóc của bạn gái xoăn tròn thành từng lọn. Mái tóc hợp nhất với ...", "a": "Nét xoắn", "w": ["Nét thẳng", "Nét gấp khúc"], "e": "Tóc xoăn cuộn thành lọn vẽ bằng nét xoắn."}, {"p": "Em vẽ mặt hồ có gợn sóng nhẹ lăn tăn. Mặt hồ hợp nhất với ...", "a": "Nét cong", "w": ["Nét gấp khúc", "Nét thẳng"], "e": "Gợn sóng mặt hồ mềm nên vẽ bằng nét cong."}, {"p": "Em vẽ bậc thang đi lên sân khấu, từng bậc gãy nhau. Bậc thang hợp nhất với ...", "a": "Nét gấp khúc", "w": ["Nét cong", "Nét xoắn"], "e": "Bậc thang gãy từng đoạn nên vẽ bằng nét gấp khúc."}, {"p": "Em dùng thước kẻ đường lề trong vở cho thật đều. Đường lề đó là ...", "a": "Nét thẳng", "w": ["Nét cong", "Nét xoắn"], "e": "Đường kẻ bằng thước là nét thẳng đều."}, {"p": "Em vẽ sợi dây leo quấn quanh hàng rào, cuộn từng vòng tròn. Dây leo hợp nhất với ...", "a": "Nét xoắn", "w": ["Nét thẳng", "Nét cong"], "e": "Dây leo cuộn vòng quanh rào vẽ bằng nét xoắn."}], "choose": [{"f": "X1", "p": "Vì sao khi vẽ nét thẳng em nên dùng thước kẻ?", "a": "Để đường thẳng đều và không bị lệch", "w": ["Để nét vẽ cong đẹp hơn", "Để giấy vẽ không bị rách", "Để màu tô được đều hơn"], "e": "Thước kẻ giúp em vẽ nét thẳng đều, không lệch."}, {"f": "X1", "p": "Bạn vẽ xong một nét cuộn tròn đều tăm tắp. Nét đó hợp để vẽ vật nào?", "a": "Cuộn len tròn của bà", "w": ["Cột cờ ở sân trường", "Tia chớp trên bầu trời", "Hàng rào thẳng đều"], "e": "Nét xoắn cuộn tròn hợp để vẽ cuộn len."}, {"f": "X1", "p": "Em muốn nét gấp khúc trong tranh trông thật sắc và rõ. Em vẽ vật nào?", "a": "Răng của chiếc cưa gỗ", "w": ["Sợi dây phơi võng xuống", "Cuộn len tròn của bà", "Đường ray xe lửa thẳng"], "e": "Răng cưa gãy khúc sắc nhọn nên vẽ bằng nét gấp khúc."}, {"f": "X1", "p": "Nét vẽ nào không có điểm gãy và cũng không cuộn thành vòng tròn?", "a": "Nét cong", "w": ["Nét thẳng", "Nét gấp khúc", "Nét xoắn"], "e": "Nét cong uốn mềm, không gãy và không cuộn tròn như nét xoắn."}], "tf": [{"s": "Nét thẳng không có chỗ cong và cũng không có điểm gãy.", "t": true, "e": "Đúng, nét thẳng đi một đường thẳng đều."}, {"s": "Nét xoắn là nét đi thẳng một đường, không cuộn lại chút nào.", "t": false, "e": "Sai, nét xoắn cuộn tròn nhiều vòng như lò xo."}, {"s": "Nét gấp khúc gồm nhiều đoạn thẳng gãy nối tiếp nhau.", "t": true, "e": "Đúng, nét gấp khúc gãy lên gãy xuống như răng cưa."}, {"s": "Cầu vồng trên bầu trời được vẽ bằng nét gấp khúc nhọn.", "t": false, "e": "Sai, cầu vồng cong vòng nên vẽ bằng nét cong."}, {"s": "Dùng thước kẻ giúp em vẽ nét thẳng đều hơn.", "t": true, "e": "Đúng, thước kẻ là dụng cụ giúp vẽ nét thẳng."}, {"s": "Vỏ ốc sên được vẽ bằng một nét thẳng đứng.", "t": false, "e": "Sai, vỏ ốc cuộn tròn nên vẽ bằng nét xoắn."}], "match": [["Cột cờ và đường ray", "để vẽ bằng nét thẳng đều"], ["Sóng nước và cầu vồng", "để vẽ bằng nét cong mềm"], ["Tia chớp và dãy núi", "để vẽ bằng nét gấp khúc nhọn"], ["Vỏ ốc và lò xo", "để vẽ bằng nét xoắn tròn"], ["Sợi dây phơi võng xuống", "để vẽ bằng nét cong nhẹ"], ["Bậc thang và răng cưa", "để vẽ bằng nét gấp khúc đều"]]}});
