(function(){var b=window.__ADV4BANKS24["tn1-community"]=window.__ADV4BANKS24["tn1-community"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Vì sao khi ngồi xe máy cùng bố mẹ, em phải đội mũ bảo hiểm?", "a": "Để bảo vệ đầu khi đi trên đường", "w": ["Để trông giống người lớn", "Để đầu được nóng hơn", "Để bố mẹ khỏi nhắc nhiều"], "e": "Mũ bảo hiểm bảo vệ đầu, giúp em an toàn khi đi xe."}, {"f": "X1", "p": "Bác lao công quét rác trên phố mỗi sáng sớm. Công việc của bác giúp ích gì nhất?", "a": "Giúp đường phố sạch đẹp cho mọi người", "w": ["Giúp phố có nhiều rác hơn", "Giúp xe đi nhanh hơn hẳn", "Giúp mọi người ngủ muộn hơn"], "e": "Bác lao công giữ cho đường phố sạch đẹp."}, {"f": "X1", "p": "Ngày Tết, em chúc ông bà điều gì là tốt đẹp nhất?", "a": "Chúc ông bà mạnh khoẻ và vui vẻ", "w": ["Chúc ông bà cho em nhiều lì xì", "Chúc ông bà mua quà cho em", "Chúc xong rồi đi chơi ngay"], "e": "Lời chúc mạnh khoẻ là lời chúc tốt đẹp nhất ngày Tết."}, {"f": "X1", "p": "Em đang chơi bóng dưới lòng đường thì người lớn nhắc em dừng lại. Vì sao người lớn nhắc?", "a": "Vì xe đi lại dưới lòng đường rất nguy hiểm", "w": ["Vì bóng sẽ bẩn khi chơi ở đó", "Vì chơi ở đó không vui bằng", "Vì người lớn muốn chơi thay em"], "e": "Chơi dưới lòng đường nguy hiểm vì xe cộ qua lại."}]);b.tf=(b.tf||[]).concat([{"s": "Chú thợ xây xây nên những ngôi nhà cho mọi người ở.", "t": true, "e": "Đúng, thợ xây làm nghề xây nhà."}, {"s": "Người đi bộ chơi đùa giữa lòng đường là an toàn.", "t": false, "e": "Sai, chơi giữa lòng đường rất nguy hiểm vì có xe qua lại."}, {"s": "Đội mũ bảo hiểm khi đi xe máy giúp bảo vệ đầu.", "t": true, "e": "Đúng, mũ bảo hiểm bảo vệ đầu khi đi xe."}, {"s": "Lên xe buýt, em chen lên trước mà không cần xếp hàng.", "t": false, "e": "Sai, em cần xếp hàng chờ lên xe cho an toàn."}, {"s": "Bác lao công quét dọn giúp đường phố sạch đẹp.", "t": true, "e": "Đúng, công việc của bác giữ phố sạch đẹp."}, {"s": "Ngày Tết, em nhận lì xì rồi cất đi mà không nói lời nào.", "t": false, "e": "Sai, nhận lì xì em cần cảm ơn và chúc Tết người lớn."}]);b.blank=(b.blank||[]).concat([{"p": "Các chú thợ đang xây bức tường cao. Các chú làm việc cẩn thận để ...", "a": "Xây nhà chắc và đẹp", "w": ["Xây nhà nhanh sập", "Để tường nghiêng hẳn"], "e": "Thợ xây làm cẩn thận để nhà chắc và đẹp."}, {"p": "Lá rụng đầy trên phố. Bác lao công quét phố từ sớm để ...", "a": "Đường phố sạch đẹp", "w": ["Đường phố bẩn hơn", "Lá rụng nhiều hơn"], "e": "Bác lao công quét dọn giúp phố sạch đẹp."}, {"p": "Em ngồi sau xe máy cùng bố. Em đội mũ bảo hiểm kĩ để ...", "a": "Bảo vệ đầu an toàn", "w": ["Đội cho đẹp mắt", "Để đầu nóng hơn"], "e": "Đội mũ bảo hiểm giúp bảo vệ đầu khi đi xe."}, {"p": "Chỗ sang đường có vạch trắng kẻ sẵn. Em đi đúng trên vạch để ...", "a": "Xe dễ nhìn thấy em", "w": ["Đi giữa dòng xe", "Chạy nhanh qua đường"], "e": "Đi đúng vạch kẻ giúp xe dễ thấy và tránh em."}, {"p": "Gần đến Tết, cả nhà cùng dọn nhà sạch sẽ để ...", "a": "Đón Tết vui và gọn gàng", "w": ["Nhà bừa bộn hơn", "Khách không đến nhà"], "e": "Dọn nhà sạch giúp đón Tết vui và gọn gàng."}, {"p": "Mẹ cắm một bình hoa tươi trong nhà ngày Tết để ...", "a": "Nhà đẹp và tươi vui", "w": ["Hoa mau héo hơn", "Nhà tối hơn"], "e": "Hoa tươi ngày Tết làm nhà đẹp và vui hơn."}, {"p": "Em gặp bác bảo vệ ở cổng trường. Em khoanh tay chào bác để ...", "a": "Tỏ ra lễ phép", "w": ["Bác cho em quà", "Vào trường nhanh hơn"], "e": "Chào hỏi người lớn là lễ phép."}, {"p": "Xe buýt vừa đến bến. Em xếp hàng chờ lên xe để ...", "a": "Mọi người lên xe an toàn", "w": ["Chen lên trước nhất", "Đứng giữa lòng đường"], "e": "Xếp hàng lên xe giúp mọi người an toàn."}, {"p": "Bà cụ qua đường rất chậm. Em cùng bố dìu bà để ...", "a": "Bà qua đường an toàn", "w": ["Bà đi nhanh như chạy", "Em sang đường một mình"], "e": "Giúp bà qua đường là việc làm tốt và an toàn."}, {"p": "Trên xe buýt có cụ già đứng. Anh thanh niên nhường ghế để ...", "a": "Cụ ngồi đỡ mỏi chân", "w": ["Cụ đứng lâu hơn", "Anh ngồi chỗ khác đẹp hơn"], "e": "Nhường ghế cho người già là việc làm đẹp."}]);b.match=(b.match||[]).concat([["Chú thợ xây", "xây nhà cho mọi người ở"], ["Bác lao công", "quét rác giúp phố sạch đẹp"], ["Mũ bảo hiểm", "để bảo vệ đầu khi đi xe máy"], ["Vạch kẻ đường", "giúp người đi bộ sang đường đúng chỗ"], ["Bánh chưng ngày Tết", "để cả nhà ăn Tết cùng nhau"], ["Xe buýt", "để chở nhiều người đi lại"]]);})();
