(function(){var b=window.__ADV4BANKS24["tv1-read6"]=window.__ADV4BANKS24["tv1-read6"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Trong cầu vồng, màu nào đứng ngay sau màu lục?", "a": "Màu lam", "w": ["Màu đỏ", "Màu tím", "Màu cam"], "e": "Thứ tự cầu vồng: đỏ, cam, vàng, lục, lam, chàm, tím."}, {"f": "X1", "p": "Vì sao giữa đêm tối, bé không nhìn thấy cầu vồng?", "a": "Vì cầu vồng cần nắng sau mưa mới hiện ra", "w": ["Vì cầu vồng chỉ ở trong nhà", "Vì ban đêm cầu vồng đổi màu đen", "Vì mắt bé nhắm khi ngủ"], "e": "Cầu vồng hiện khi có nắng sau mưa, ban đêm không có nắng."}, {"f": "X1", "p": "Nhận định nào đúng nhất về cầu vồng?", "a": "Bảy màu xếp theo một thứ tự nhất định", "w": ["Bảy màu xếp lộn xộn tuỳ ý", "Chỉ có hai màu đỏ và tím", "Màu đen là màu đầu tiên"], "e": "Cầu vồng có bảy màu theo thứ tự: đỏ, cam, vàng, lục, lam, chàm, tím."}, {"f": "X1", "p": "Màu chàm nằm ở đâu trong cầu vồng?", "a": "Ở gần cuối, ngay trước màu tím", "w": ["Ở đầu tiên, trước màu đỏ", "Ở giữa, sau màu vàng", "Không có trong cầu vồng"], "e": "Màu chàm đứng thứ sáu, ngay trước màu tím cuối cùng."}]);b.tf=(b.tf||[]).concat([{"s": "Màu lam đứng ngay sau màu lục trong cầu vồng.", "t": true, "e": "Đúng, thứ tự là lục rồi đến lam."}, {"s": "Màu cam là màu cuối cùng của cầu vồng.", "t": false, "e": "Sai, màu tím mới là màu cuối cùng của cầu vồng."}, {"s": "Cầu vồng cong như một vòng cung trên bầu trời.", "t": true, "e": "Đúng, cầu vồng có hình vòng cung cong."}, {"s": "Cầu vồng chỉ có ba màu là đỏ, vàng và tím.", "t": false, "e": "Sai, cầu vồng có bảy màu."}, {"s": "Màu chàm đứng giữa màu lam và màu tím.", "t": true, "e": "Đúng, thứ tự cuối là lam, chàm rồi tím."}, {"s": "Mặt trăng là một trong bảy màu của cầu vồng.", "t": false, "e": "Sai, mặt trăng không phải là màu của cầu vồng."}]);b.blank=(b.blank||[]).concat([{"p": "Bé vẽ cầu vồng, tô màu đầu tiên là đỏ. Màu bé tô tiếp ngay sau đó là ...", "a": "Màu cam", "w": ["Màu tím", "Màu lục"], "e": "Sau màu đỏ của cầu vồng là màu cam."}, {"p": "Bé tô cầu vồng đến màu lục. Màu tiếp theo giống màu bầu trời trong là ...", "a": "Màu lam", "w": ["Màu đỏ", "Màu cam"], "e": "Sau màu lục của cầu vồng là màu lam."}, {"p": "Bé tô cầu vồng đến màu lam. Màu tiếp theo đậm hơn lam một chút là ...", "a": "Màu chàm", "w": ["Màu vàng", "Màu đỏ"], "e": "Sau màu lam của cầu vồng là màu chàm."}, {"p": "Trên trời, dải bảy màu cong cong bắc qua như một chiếc cầu. Dải màu đó có hình ...", "a": "Vòng cung cong", "w": ["Đường thẳng", "Hình vuông"], "e": "Cầu vồng cong như một vòng cung trên trời."}, {"p": "Mưa vừa tạnh và nắng vừa lên. Bé cùng bạn chạy ra sân để ...", "a": "Cùng ngắm cầu vồng", "w": ["Chạy tắm mưa tiếp", "Vào nhà ngủ trưa"], "e": "Sau mưa nắng lên, bé ra sân ngắm cầu vồng."}, {"p": "Bé vẽ cầu vồng mới tô được ba màu. Bé tô thêm bốn màu nữa để ...", "a": "Đủ bảy màu cầu vồng", "w": ["Tranh có ba màu thôi", "Màu nào cũng giống nhau"], "e": "Cầu vồng có bảy màu nên bé tô đủ bảy màu."}, {"p": "Mưa xong, nắng chiếu qua những giọt nước còn đọng. Trên trời dần hiện ...", "a": "Dải bảy màu cầu vồng", "w": ["Dải mây đen dày", "Mặt trăng tròn"], "e": "Sau mưa nắng lên, cầu vồng bảy màu hiện trên trời."}, {"p": "Bé chỉ vào màu lục trên cầu vồng. Màu lục ấy giống màu của ...", "a": "Ngọn cỏ non", "w": ["Quả táo chín", "Chùm nho chín"], "e": "Màu lục giống màu xanh của ngọn cỏ non."}, {"p": "Nắng sau mưa hơi chói mắt. Bé lấy tay che nhẹ trên trán để ...", "a": "Nhìn cầu vồng rõ hơn", "w": ["Ngủ gật giữa sân", "Che mưa đang rơi"], "e": "Che tay nhẹ giúp bé đỡ chói và nhìn cầu vồng rõ hơn."}, {"p": "Chiều nay mưa xong trời trong và sáng. Bé đứng ngắm trời và thấy ...", "a": "Không khí mát và dễ chịu", "w": ["Trời tối như ban đêm", "Mưa rơi nặng hạt hơn"], "e": "Sau mưa, trời trong sáng và không khí mát dễ chịu."}]);b.match=(b.match||[]).concat([["Màu cam", "để tô sau màu đỏ trong cầu vồng"], ["Màu lam", "giống màu bầu trời trong xanh"], ["Màu chàm", "đứng trước màu tím trong cầu vồng"], ["Màu lục", "giống màu ngọn cỏ non"], ["Cầu vồng sau mưa", "để bé ngắm bảy sắc màu đẹp"], ["Dải màu cong", "là hình của cầu vồng trên trời"]]);})();
