(function(){var b=window.__ADV4BANKS24["tv1-read3"]=window.__ADV4BANKS24["tv1-read3"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Vì sao trong giờ học, em cần giơ tay trước khi phát biểu?", "a": "Để lớp trật tự và cô nghe rõ em nói", "w": ["Để tay em cao hơn bạn", "Để cô không dạy bài nữa", "Để bạn khác không được nói"], "e": "Giơ tay giúp lớp trật tự và ai cũng được phát biểu."}, {"f": "X1", "p": "Sân trường có nhiều lá khô rụng. Việc làm nào là đúng nhất?", "a": "Cùng bạn nhặt lá bỏ vào thùng rác", "w": ["Quét lá sang sân lớp khác", "Để lá đầy sân cho đẹp", "Giẫm lên lá chơi cho vui"], "e": "Nhặt lá bỏ thùng rác giữ sân trường sạch đẹp."}, {"f": "X1", "p": "Bạn mới vào trường chưa biết lớp học ở đâu. Em nên làm gì?", "a": "Chỉ đường và dẫn bạn đến lớp", "w": ["Mặc kệ để bạn tự tìm", "Trêu bạn vì không biết đường", "Bảo bạn về nhà đi"], "e": "Giúp bạn mới tìm lớp là việc làm thân thiện."}, {"f": "X1", "p": "Em luyện viết chữ mỗi ngày ở nhà. Việc luyện viết giúp em điều gì nhất?", "a": "Chữ viết rõ ràng và đẹp dần lên", "w": ["Viết được ít chữ hơn", "Không cần học ở lớp nữa", "Bạn bè không đọc được chữ em"], "e": "Luyện viết thường xuyên giúp chữ rõ và đẹp hơn."}]);b.tf=(b.tf||[]).concat([{"s": "Sáng thứ hai, cả trường cùng dự lễ chào cờ.", "t": true, "e": "Đúng, chào cờ đầu tuần là hoạt động của cả trường."}, {"s": "Trong giờ học, em tự nói thật to mà không cần giơ tay.", "t": false, "e": "Sai, em cần giơ tay và chờ cô mời mới phát biểu."}, {"s": "Nhặt lá rụng bỏ vào thùng rác giúp sân trường sạch.", "t": true, "e": "Đúng, giữ sân trường sạch là việc của mọi người."}, {"s": "Xếp hàng vào lớp, em chen lên trước cho nhanh.", "t": false, "e": "Sai, xếp hàng em đi nhẹ và không chen lấn."}, {"s": "Luyện viết mỗi ngày giúp chữ của em đẹp dần.", "t": true, "e": "Đúng, luyện tập thường xuyên giúp chữ tiến bộ."}, {"s": "Trời mưa lúc tan học, em chạy một mình ra cổng cho nhanh.", "t": false, "e": "Sai, em chờ bố mẹ ở hiên trường cho an toàn."}]);b.blank=(b.blank||[]).concat([{"p": "Sáng thứ hai, cả trường tập trung ở sân. Em đứng nghiêm hát cùng mọi người để ...", "a": "Dự lễ chào cờ", "w": ["Về lớp sớm hơn bạn", "Chơi đùa ở sân"], "e": "Sáng thứ hai, cả trường dự lễ chào cờ."}, {"p": "Em chưa biết lớp học mới ở đâu. Em lễ phép hỏi cô giáo để ...", "a": "Cô chỉ đường đến lớp", "w": ["Cô cho em nghỉ học", "Em tự đi tìm cả ngày"], "e": "Hỏi cô giáo giúp em biết đường đến lớp mới."}, {"p": "Giờ học, em biết câu trả lời. Em giơ tay cao và chờ cô mời để ...", "a": "Được phát biểu trả lời", "w": ["Nói chen thật to", "Trả lời thay bạn khác"], "e": "Giơ tay và chờ cô mời là nề nếp giờ học."}, {"p": "Lá khô rụng đầy sân trường. Cả lớp cùng nhặt lá bỏ thùng rác để ...", "a": "Sân trường sạch đẹp", "w": ["Sân trường nhiều lá hơn", "Được nghỉ học sớm"], "e": "Nhặt lá giúp sân trường sạch đẹp."}, {"p": "Chậu hoa ở sân trường bị khô đất. Em tưới một ít nước cho hoa để ...", "a": "Cây hoa tươi tốt", "w": ["Cây hoa héo nhanh hơn", "Đất khô hơn nữa"], "e": "Tưới nước giúp cây hoa tươi tốt."}, {"p": "Đến giờ xếp hàng vào lớp. Em đi nhẹ, không chen lấn để ...", "a": "Cả hàng đi ngay ngắn", "w": ["Em vào lớp trước nhất", "Hàng đi lộn xộn hơn"], "e": "Đi nhẹ và không chen giúp hàng ngay ngắn."}, {"p": "Bạn cùng bàn đọc một chữ chưa rõ. Em chỉ tay vào chữ và đọc cùng bạn để ...", "a": "Giúp bạn đọc đúng hơn", "w": ["Bạn đọc sai thêm", "Cô khỏi dạy bài"], "e": "Đọc cùng giúp bạn đọc đúng và tự tin hơn."}, {"p": "Trống tan học đã vang nhưng trời đang mưa to. Em chờ bố mẹ ở hiên trường để ...", "a": "Không bị ướt mưa", "w": ["Chạy ra cổng một mình", "Đứng giữa sân tắm mưa"], "e": "Chờ ở hiên giúp em không bị ướt mưa."}, {"p": "Chữ viết của em chưa đẹp. Mỗi ngày em luyện viết thêm một trang để ...", "a": "Chữ viết đẹp dần lên", "w": ["Chữ viết xấu đi", "Vở mau hết giấy"], "e": "Luyện viết mỗi ngày giúp chữ đẹp dần."}, {"p": "Sách của lớp để lẫn lộn trên kệ. Em cùng bạn xếp sách ngay ngắn để ...", "a": "Lớp dễ tìm sách học", "w": ["Kệ sách bừa hơn", "Sách mau cũ hơn"], "e": "Xếp sách ngay ngắn giúp lớp dễ tìm sách."}]);b.match=(b.match||[]).concat([["Lễ chào cờ", "để bắt đầu tuần học mới trang nghiêm"], ["Sân trường sạch", "giúp em chơi an toàn và vui"], ["Kệ sách của lớp", "để xếp sách ngay ngắn dễ tìm"], ["Cây hoa ở sân trường", "cần tưới nước để tươi tốt"], ["Giơ tay phát biểu", "để cô mời em trả lời"], ["Hiên trường khi mưa", "để chờ bố mẹ đón an toàn"]]);})();
