(function(){var b=window.__ADV4BANKS24["tv1-read5"]=window.__ADV4BANKS24["tv1-read5"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Kiến cắn vào chân người thợ săn khi thợ săn sắp bắn bồ câu. Việc làm của kiến cho thấy điều gì?", "a": "Kiến biết trả ơn người đã cứu mình", "w": ["Kiến muốn giúp thợ săn", "Kiến tình cờ đi ngang qua", "Kiến sợ bồ câu bay mất"], "e": "Bồ câu từng cứu kiến, nay kiến cứu lại bồ câu để trả ơn."}, {"f": "X1", "p": "Vì sao em nên giữ đúng lời hứa với bạn?", "a": "Vì giữ lời hứa giúp bạn tin tưởng em", "w": ["Vì hứa rồi quên cũng không sao", "Vì bạn sẽ cho em nhiều đồ hơn", "Vì cô giáo luôn đứng cạnh nghe"], "e": "Giữ lời hứa làm bạn bè tin tưởng và quý mến em."}, {"f": "X1", "p": "Em lỡ làm bạn buồn. Cách làm nào là đúng nhất?", "a": "Xin lỗi bạn và không làm lại nữa", "w": ["Im lặng như không có chuyện gì", "Đổ lỗi cho bạn khác", "Chọc bạn khóc thêm lần nữa"], "e": "Xin lỗi và sửa sai là cách làm đúng khi em có lỗi."}, {"f": "X1", "p": "Câu chuyện kiến và bồ câu dạy em bài học gì?", "a": "Biết giúp nhau lúc khó khăn là điều quý", "w": ["Ai mạnh hơn thì thắng hết", "Được giúp rồi quên ngay cũng được", "Chỉ chơi với bạn giống mình"], "e": "Câu chuyện dạy em biết giúp đỡ và nhớ ơn nhau."}]);b.tf=(b.tf||[]).concat([{"s": "Kiến đã cứu lại bồ câu khi bồ câu gặp nạn.", "t": true, "e": "Đúng, kiến cắn chân thợ săn để cứu bồ câu."}, {"s": "Kiến quên ngay ơn cứu giúp của bồ câu và bỏ đi.", "t": false, "e": "Sai, kiến nhớ ơn và đã cứu lại bồ câu."}, {"s": "Giữ đúng lời hứa giúp bạn bè tin tưởng em.", "t": true, "e": "Đúng, người giữ lời hứa được mọi người tin yêu."}, {"s": "Làm bạn buồn, em cứ im lặng không cần xin lỗi.", "t": false, "e": "Sai, em cần xin lỗi bạn khi làm bạn buồn."}, {"s": "Nhặt được đồ của bạn rơi, em trả lại cho bạn.", "t": true, "e": "Đúng, trả lại đồ nhặt được là thật thà."}, {"s": "Làm vỡ đồ trong nhà, em giấu kín là cách làm đúng nhất.", "t": false, "e": "Sai, em cần kể thật và nhận lỗi khi làm vỡ đồ."}]);b.blank=(b.blank||[]).concat([{"p": "Thợ săn giơ súng nhắm vào bồ câu. Kiến bò đến cắn vào chân thợ săn để ...", "a": "Cứu bồ câu thoát nạn", "w": ["Giúp thợ săn bắn trúng", "Chạy trốn một mình"], "e": "Kiến cắn chân thợ săn làm súng lệch, bồ câu bay thoát."}, {"p": "Ngày trước bồ câu đã cứu kiến khỏi dòng nước. Nay kiến cứu lại bồ câu để ...", "a": "Trả ơn bồ câu đã cứu mình", "w": ["Quên ơn của bồ câu", "Làm bồ câu sợ hãi"], "e": "Kiến nhớ ơn và trả ơn bồ câu đã cứu mình."}, {"p": "Em nhặt được chiếc bút của bạn rơi dưới bàn. Em đưa lại cho bạn để ...", "a": "Bạn có bút học bài", "w": ["Bạn khỏi cần bút nữa", "Em giữ bút cho mình"], "e": "Trả lại đồ nhặt được là thật thà và tốt bụng."}, {"p": "Em hứa chiều nay trả cuốn truyện cho bạn. Đến chiều, em mang truyện đến trả để ...", "a": "Giữ lời hứa với bạn", "w": ["Bạn quên mất truyện", "Em mượn truyện lâu hơn"], "e": "Trả đúng hẹn cho thấy em giữ lời hứa."}, {"p": "Em lỡ làm bạn buồn trong giờ chơi. Em đến bên bạn và nói ...", "a": "Xin lỗi bạn nhé", "w": ["Mặc kệ bạn luôn", "Bạn tự buồn tự chịu"], "e": "Làm bạn buồn, em xin lỗi bạn chân thành."}, {"p": "Bạn bị ngã ở sân, đầu gối rất đau. Em đỡ bạn dậy và gọi cô đến để ...", "a": "Bạn được cô chăm sóc", "w": ["Bạn tự đứng dậy một mình", "Cả lớp chạy đi chơi"], "e": "Đỡ bạn và gọi cô giúp bạn được chăm sóc kịp thời."}, {"p": "Trời mưa to, bạn quên mang ô. Em đi gần lại và che ô chung với bạn để ...", "a": "Cả hai không bị ướt", "w": ["Bạn ướt hết người", "Em đi nhanh về trước"], "e": "Che ô chung giúp cả hai bạn không bị ướt mưa."}, {"p": "Bé chăn cừu đã biết lỗi của mình. Bé đến gặp mọi người trong làng và ...", "a": "Xin lỗi mọi người", "w": ["Hô dối thêm lần nữa", "Giấu mặt không gặp ai"], "e": "Biết lỗi và xin lỗi giúp bé sửa sai."}, {"p": "Sau khi thoát nạn trên chiếc lá, kiến quay lại phía bồ câu để ...", "a": "Cảm ơn bồ câu đã cứu", "w": ["Giận bồ câu vô ơn", "Bỏ đi không nói gì"], "e": "Được cứu, kiến cảm ơn bồ câu."}, {"p": "Em lỡ làm vỡ chiếc cốc của mẹ. Em kể thật mọi chuyện với mẹ để ...", "a": "Mẹ biết và tha lỗi cho em", "w": ["Mẹ không bao giờ biết", "Em khỏi bị nhắc nhở"], "e": "Kể thật khi làm sai giúp em được tha lỗi và sửa sai."}]);b.match=(b.match||[]).concat([["Kiến cứu bồ câu", "để trả ơn người đã giúp mình"], ["Em hứa với bạn", "để giữ đúng lời đã hứa"], ["Em làm bạn buồn", "để xin lỗi bạn chân thành"], ["Nhặt được bút rơi", "để trả lại cho bạn mất bút"], ["Bạn ngã đau chân", "để đỡ bạn và gọi cô giúp"], ["Trời mưa bạn quên ô", "để che ô chung cùng bạn"]]);})();
