(function(){var b=window.__ADV4BANKS24["tv1-read7"]=window.__ADV4BANKS24["tv1-read7"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Con vật nào vừa sống trên cạn, vừa bơi được dưới nước?", "a": "Con ếch", "w": ["Con cá", "Con chim", "Con thỏ"], "e": "Ếch sống trên cạn và bơi dưới nước; cá chỉ ở nước, chim bay, thỏ ở cạn."}, {"f": "X1", "p": "Vì sao vào mùa hè, em mau thấy khát nước hơn?", "a": "Vì trời nóng làm em ra nhiều mồ hôi", "w": ["Vì mùa hè trời lạnh hơn", "Vì em uống nước nhiều quá", "Vì nước tự bay hết khỏi cốc"], "e": "Trời nóng làm cơ thể ra mồ hôi nên em mau khát."}, {"f": "X1", "p": "Bé cầm cốc nước đá và thấy lạnh buốt. Bé cảm nhận được điều đó bằng gì?", "a": "Bàn tay", "w": ["Đôi tai", "Cái mũi", "Cái lưỡi"], "e": "Bé sờ cốc bằng tay nên cảm nhận được lạnh."}, {"f": "X1", "p": "Mùa nào trong năm trời lạnh nhất, em cần mặc áo ấm dày?", "a": "Mùa đông", "w": ["Mùa xuân", "Mùa hè", "Mùa thu"], "e": "Mùa đông trời lạnh nhất, em cần mặc ấm."}]);b.tf=(b.tf||[]).concat([{"s": "Em ngửi mùi thơm của hoa bằng mũi.", "t": true, "e": "Đúng, mũi dùng để ngửi mùi."}, {"s": "Em nếm vị ngọt của kẹo bằng tai.", "t": false, "e": "Sai, tai dùng để nghe; nếm vị là việc của lưỡi."}, {"s": "Mùa hè trời nóng và có nhiều nắng.", "t": true, "e": "Đúng, mùa hè nắng nóng."}, {"s": "Mùa đông là mùa nóng nhất trong năm.", "t": false, "e": "Sai, mùa đông lạnh; mùa hè mới nóng."}, {"s": "Con bướm bay và đậu trên hoa để hút mật.", "t": true, "e": "Đúng, bướm đậu trên hoa hút mật."}, {"s": "Con ếch chỉ sống trên cành cây cao.", "t": false, "e": "Sai, ếch sống ở gần ao nước và trên cạn."}]);b.blank=(b.blank||[]).concat([{"p": "Trong vườn, hoa hồng toả mùi thơm ngát. Em ngửi được mùi thơm ấy bằng ...", "a": "Cái mũi", "w": ["Đôi tai", "Cái lưỡi"], "e": "Em ngửi mùi thơm bằng mũi."}, {"p": "Mẹ cho em ăn một miếng cam chua ngọt. Em nếm được vị của cam bằng ...", "a": "Cái lưỡi", "w": ["Đôi mắt", "Bàn tay"], "e": "Em nếm vị chua ngọt bằng lưỡi."}, {"p": "Con bướm bay vòng quanh vườn hoa rồi đậu xuống một bông hoa để ...", "a": "Hút mật hoa", "w": ["Ngủ trong đất", "Bơi dưới nước"], "e": "Bướm đậu trên hoa để hút mật."}, {"p": "Mùa hè trời rất nóng. Em đội mũ và uống nhiều nước để ...", "a": "Người mát và đỡ khát", "w": ["Người nóng hơn nữa", "Chạy chơi giữa trưa nắng"], "e": "Đội mũ và uống nước giúp em đỡ nóng và đỡ khát."}, {"p": "Mùa đông gió lạnh thổi mạnh. Em mặc áo ấm và quàng khăn khi ra ngoài để ...", "a": "Người không bị lạnh", "w": ["Người lạnh hơn nữa", "Áo mỏng cho mát"], "e": "Mặc ấm và quàng khăn giúp em không bị lạnh."}, {"p": "Đàn kiến bò thành hàng dài trên sân. Em cúi xuống ngắm đàn kiến để ...", "a": "Xem kiến đi tìm thức ăn", "w": ["Đếm sao trên trời", "Nghe chim hót"], "e": "Quan sát đàn kiến giúp em hiểu thêm về thế giới quanh em."}, {"p": "Sau cơn mưa, lá cây được rửa sạch bụi. Em ngắm những chiếc lá và thấy ...", "a": "Lá sạch và xanh hơn", "w": ["Lá vàng và khô hơn", "Lá biến mất hết"], "e": "Mưa rửa sạch bụi làm lá xanh và sạch hơn."}, {"p": "Chiều tối, tiếng ếch kêu râm ran ngoài ao. Em lắng tai nghe để ...", "a": "Đoán ếch ở gần ao nước", "w": ["Nhìn thấy sao băng", "Ngửi mùi hoa thơm"], "e": "Tiếng ếch kêu cho em biết ếch ở gần ao."}, {"p": "Mùa thu, lá vàng rơi đầy sân. Em nhặt một chiếc lá vàng đẹp để ...", "a": "Ép lá vào vở ngắm", "w": ["Ném lá xuống ao", "Xé lá ra từng mảnh"], "e": "Nhặt và ép chiếc lá vàng giúp em giữ kỉ niệm mùa thu."}, {"p": "Cây bàng trước sân rụng nhiều lá. Em cùng bạn quét lá gọn vào một chỗ để ...", "a": "Sân sạch để chơi", "w": ["Sân đầy lá hơn", "Lá bay khắp nơi"], "e": "Quét lá gọn giúp sân sạch và an toàn để chơi."}]);b.match=(b.match||[]).concat([["Cái mũi", "để ngửi mùi thơm của hoa"], ["Cái lưỡi", "để nếm vị ngọt và chua"], ["Bàn tay", "để sờ và biết nóng lạnh"], ["Mùa hè", "là lúc trời nắng nóng nhiều"], ["Mùa đông", "là lúc trời lạnh cần áo ấm"], ["Con ếch", "sống ở gần ao nước mát"]]);})();
