(function(){var b=window.__ADV4BANKS24["tv1-read1"]=window.__ADV4BANKS24["tv1-read1"]||{};b.choose=(b.choose||[]).concat([{"f": "X1", "p": "Vì sao em nên cho bạn dùng chung hộp màu khi bạn quên mang?", "a": "Vì chia sẻ giúp bạn học tốt và thêm vui", "w": ["Vì bạn sẽ cho em hết màu của bạn", "Vì em không cần dùng màu nữa", "Vì cô giáo bắt em phải cho"], "e": "Chia sẻ đồ dùng giúp bạn học tốt và tình bạn thêm gắn bó."}, {"f": "X1", "p": "Bạn mới vào lớp còn rụt rè, ít nói. Việc em rủ bạn chơi cùng giúp bạn điều gì nhất?", "a": "Giúp bạn bớt buồn và quen lớp nhanh hơn", "w": ["Giúp bạn học thay phần của em", "Giúp bạn không cần làm quen ai nữa", "Giúp em có thêm đồ chơi mới"], "e": "Được rủ chơi cùng, bạn mới sẽ vui và quen lớp nhanh."}, {"f": "X1", "p": "Em và bạn cùng thích một món đồ chơi trong lớp. Cách làm nào là tốt nhất?", "a": "Chơi chung và thay phiên nhau", "w": ["Giành lấy chơi một mình", "Giấu đồ chơi đi chỗ khác", "Bảo bạn không được chơi"], "e": "Chơi chung và thay phiên giúp hai bạn đều vui."}, {"f": "X1", "p": "Bạn cùng lớp được cô khen vì đọc bài tốt. Em nên làm gì?", "a": "Chúc mừng bạn và học theo bạn", "w": ["Im lặng quay đi chỗ khác", "Chê bạn đọc chưa hay", "Đòi cô khen em ngay"], "e": "Chúc mừng bạn và học theo bạn là thái độ tốt."}]);b.tf=(b.tf||[]).concat([{"s": "Cho bạn dùng chung màu vẽ khi bạn quên mang là việc tốt.", "t": true, "e": "Đúng, chia sẻ đồ dùng giúp bạn học tốt."}, {"s": "Giành đồ chơi và không cho bạn chơi cùng là ngoan.", "t": false, "e": "Sai, em cần chơi chung và nhường nhịn bạn."}, {"s": "Bạn được cô khen, em vui và chúc mừng bạn.", "t": true, "e": "Đúng, chúc mừng bạn là tình bạn đẹp."}, {"s": "Bạn làm mất đồ, em cười chê và giấu đồ của bạn.", "t": false, "e": "Sai, em nên giúp bạn tìm đồ, không chê cười bạn."}, {"s": "Rủ bạn mới chơi cùng giúp bạn quen lớp nhanh hơn.", "t": true, "e": "Đúng, bạn mới được rủ chơi sẽ bớt rụt rè."}, {"s": "Xếp hàng chờ đến lượt, em đẩy bạn để đứng lên trước.", "t": false, "e": "Sai, em cần xếp hàng ngay ngắn, không xô đẩy bạn."}]);b.blank=(b.blank||[]).concat([{"p": "Bạn vẽ được một bức tranh rất đẹp. Em mỉm cười nhìn bạn và nói ...", "a": "Bạn vẽ đẹp lắm", "w": ["Bạn vẽ xấu lắm", "Tớ vẽ đẹp hơn bạn"], "e": "Khen bạn khi bạn làm tốt giúp bạn vui và tự tin."}, {"p": "Ghế ngồi trong lớp còn ít, bạn đến sau chưa có chỗ. Em nhích sang một bên để ...", "a": "Bạn có chỗ ngồi học", "w": ["Bạn đứng học cả buổi", "Em ngồi rộng hơn nữa"], "e": "Nhường chỗ cho bạn là biết chia sẻ."}, {"p": "Bạn quên mang hộp màu vẽ. Em đưa hộp màu của mình cho bạn dùng chung để ...", "a": "Bạn tô xong bức tranh", "w": ["Bạn khỏi học vẽ luôn", "Em không cần tô nữa"], "e": "Cho bạn dùng chung màu giúp bạn hoàn thành bài vẽ."}, {"p": "Bạn cúi xuống nhặt giúp em chồng sách bị rơi. Em nhìn bạn và nói ...", "a": "Cảm ơn bạn nhé", "w": ["Bạn nhặt chậm quá", "Lần sau đừng nhặt nữa"], "e": "Bạn giúp em, em nói cảm ơn bạn."}, {"p": "Em đi vội và lỡ va nhẹ vào bạn. Em dừng lại ngay và nói ...", "a": "Cho tớ xin lỗi nhé", "w": ["Bạn tự tránh đi chứ", "Tớ không cố ý đâu mà cãi"], "e": "Va vào bạn, em xin lỗi bạn chân thành."}, {"p": "Bạn mới vào lớp còn rụt rè, chưa dám ra chơi. Em rủ bạn ra sân cùng để ...", "a": "Bạn chơi vui cùng lớp", "w": ["Bạn đứng xem một mình", "Em chơi với nhóm khác"], "e": "Rủ bạn mới chơi cùng giúp bạn bớt rụt rè."}, {"p": "Bạn buồn vì tìm mãi không thấy cục tẩy. Em cùng bạn tìm quanh lớp để ...", "a": "Giúp bạn tìm lại tẩy", "w": ["Bạn mất tẩy luôn", "Em tìm đồ của em thôi"], "e": "Cùng tìm giúp bạn tìm lại đồ đã mất."}, {"p": "Cô khen bạn đọc bài to và rõ. Cả lớp cùng vỗ tay để ...", "a": "Chúc mừng bạn", "w": ["Bạn đọc lại từ đầu", "Cô khen em thay bạn"], "e": "Vỗ tay chúc mừng khi bạn làm tốt."}, {"p": "Sau giờ chơi nắng, bạn ngồi thở mệt. Em quạt nhẹ cho bạn bằng bìa để ...", "a": "Bạn đỡ nóng và mát hơn", "w": ["Bạn chạy chơi tiếp ngay", "Em quạt cho mình thôi"], "e": "Quạt cho bạn lúc bạn mệt là quan tâm bạn."}, {"p": "Trò kéo co vừa xong, hai đội đều thấm mệt. Em bắt tay bạn đội bên kia để ...", "a": "Hai đội vẫn vui vẻ", "w": ["Đội bạn buồn hơn nữa", "Em thắng nên cười to"], "e": "Bắt tay sau trò chơi giúp hai đội vui vẻ với nhau."}]);b.match=(b.match||[]).concat([["Bạn quên màu vẽ", "để cho bạn dùng chung màu"], ["Bạn nhặt sách giúp em", "để nói cảm ơn bạn"], ["Bạn mới vào lớp", "để rủ bạn chơi cùng lớp"], ["Bạn vẽ tranh đẹp", "để khen và chúc mừng bạn"], ["Hai bạn thích một đồ chơi", "để chơi chung thay phiên nhau"], ["Bạn tìm không thấy tẩy", "để cùng bạn tìm quanh lớp"]]);})();
